package com.studenthub.controller;import com.studenthub.dao.AttachmentDAO;import com.studenthub.util.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet(name="AttachmentServlet",urlPatterns="/attachments/*") public class AttachmentServlet extends HttpServlet{private final AttachmentDAO dao=new AttachmentDAO();private final AttachmentStorage storage=new AttachmentStorage();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{HttpSession session=q.getSession(false);if(!Authorization.isAuthenticated(session)){r.sendRedirect(q.getContextPath()+"/login");return;}try{String p=q.getPathInfo();if(p==null||!p.matches("/\\d+")){r.sendError(404);return;}var a=dao.findById(Long.parseLong(p.substring(1))).orElse(null);if(a==null||!dao.visibleTo(a,(Long)session.getAttribute("userId"))){r.sendError(404);return;}var file=storage.find(a.storageKey()).orElse(null);if(file==null){r.sendError(404);return;}MediaResponse.serve(q,r,a,file);}catch(Exception e){getServletContext().log("Attachment delivery failed: "+e.getClass().getName());if(!r.isCommitted())r.sendError(404);}}}
